\begin{align*}
a + b \omega + c \omega^2 &= a + b \left( ``-\frac{1}{2} + \frac{i \sqrt{3}}{2}\right) + c \left( -\frac{1}{2} - \frac{i \sqrt{3}}{2}\right) \\
